function body(t: Topic): readonly string[] {
  return [t.opening, t.situation, t.ownerDecision, t.assistantWork, t.evidence, t.failure, t.example, t.measure, t.handoff, t.close, ...extensions[t.slug].paragraphs];
}

function sections(t: Topic) {
  const paragraphs = body(t);
  const core = t.headings.map((title, index) => ({
    title,
    paragraphs: paragraphs.slice(index * 2, index * 2 + 2),
    checks: index === 0
      ? ['Is the work unit explicit?', 'What evidence starts the task?', 'Who accepts the result?']
      : index === 4
        ? ['What remains unresolved?', 'Who owns the next decision?', 'How will the public result be verified?']
        : ['What was directly observed?', 'Which action stays within the role?', 'Where is the decision recorded?'],
  }));
  return [...core, { title: extensions[t.slug].title, paragraphs: extensions[t.slug].paragraphs, checks: ['What evidence supports the decision?', 'Which boundary protects the role?', 'What condition closes the work?'] }];
}

export const sep3BlogPosts = topics.map((topic) => ({
  slug: topic.slug,
  title: topic.title,
  excerpt: topic.excerpt,
  minutes: 9,
  publishedAt,
}));

export const sep3BlogBasics = Object.fromEntries(topics.map((topic) => [topic.slug, {
  intro: topic.opening,
  sections: sections(topic),
}]));
